    private void viewReceiptButtonActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_viewReceiptButtonActionPerformed
        Order order = selectedOrder();
        if (order != null) {
            Ui.showReceipt(this, order);
        }
    }//GEN-LAST:event_viewReceiptButtonActionPerformed

    private java.util.List<Order> orders = new java.util.ArrayList<>();

    private void loadOrders() {
        int previous = Math.max(0, orderCombo.getSelectedIndex());
        orders = Session.getMyOrders();
        javax.swing.DefaultComboBoxModel<String> model = new javax.swing.DefaultComboBoxModel<>();
        for (Order order : orders) {
            model.addElement("Order " + order.getNumber());
        }
        orderCombo.setModel(model);
        boolean hasOrders = !orders.isEmpty();
        orderCard.setVisible(hasOrders);
        orderCombo.setVisible(hasOrders);
        orderPickerLabel.setVisible(hasOrders);
        emptyLabel.setVisible(!hasOrders);
        emptyButton.setVisible(!hasOrders);
        if (hasOrders) {
            orderCombo.setSelectedIndex(Math.min(previous, orders.size() - 1));
        }
        showSelectedOrder();
    }

    private Order selectedOrder() {
        int index = orderCombo.getSelectedIndex();
        return index >= 0 && index < orders.size() ? orders.get(index) : null;
    }

    private void showSelectedOrder() {
        Order order = selectedOrder();
        if (order == null) {
            return;
        }
        orderNumberLabel.setText("Order " + order.getNumber());
        orderDateLabel.setText(order.getCreatedAt().format(Ui.DATE) + "     " + order.getCreatedAt().format(Ui.TIME));
        Ui.statusBadge(statusBadge, order);
        itemIconLabel.setIcon(Ui.icon(order.getIcon()));
        serviceLabel.setText(order.getService());
        weightLabel.setText(Ui.kg(order.getWeightKg()) + "  \u2022  " + Ui.peso(order.getPricePerKg()) + " / kg");
        priceLabel.setText(Ui.peso(order.getTotal()));

        trackingProgress.setCurrentStep(order.getStatus() + 1);
        String[] recordedTimes = new String[6];
        recordedTimes[0] = order.getCreatedAt().format(Ui.TIME);
        for (int step = 0; step <= order.getStatus(); step++) {
            java.time.LocalDateTime when = order.getStatusTime(step);
            if (when != null) recordedTimes[step + 1] = when.format(Ui.TIME);
        }
        trackingProgress.setTimestamps(recordedTimes);
        customerValueLabel.setText(order.getCustomerName());
        phoneValueLabel.setText(order.getCustomerPhone());
        completionValueLabel.setText(order.getExpectedCompletion().format(Ui.DATE));
        paymentValueLabel.setText(order.getPaymentMethod());
        paymentStatusValueLabel.setText(order.getPaymentStatus());
        amountDueValueLabel.setText(Ui.peso(order.getAmountDue()));
        noteValueLabel.setText(order.getStaffNote().isEmpty() ? "-" : order.getStaffNote());
        viewReceiptButton.setText("View " + Ui.documentName(order));
    }

    public static void main(String args[]) {
        Ui.installLookAndFeel();
        if (!Database.start()) { // connects to MySQL and creates the tables on first run
            return;
        }
        Session.ensurePreviewUser(); // lets this screen run on its own (Shift+F6)
        java.awt.EventQueue.invokeLater(() -> new MyOrdersForm().setVisible(true));
    }

